import pickle, sys
from collections import Counter
LV, TH, WP = pickle.load(open('G:/temp/studio/levels-lv.pkl', 'rb'))
OBJ = {'eliminate': 'выбить всех', 'survive_turns': 'продержаться', 'collect_crates': 'ящики', 'rescue': 'спасти', 'one_turn_kill': 'один ход', 'destroy_objects': 'разбить предметы', 'reach_point': 'дойти до точки', 'protect': 'защитить', 'king_of_hill': 'царь горы', 'race_time': 'гонка', 'targets': 'мишени'}
TM = {'day': 'день', 'evening': 'вечер', 'night': 'ночь', 'grey': 'серый день', 'winter': 'зимний день'}

def row(l, extra=''):
    return f"| {l['id']} | {l['title']} | {TH[l['theme']]['title']} | {TM[l['time']]} | {l['terrain']['archetype']} | {OBJ[l['objective']['type']]} | {l['new'] or '—'}{extra} |"

head = "| id | Название | Тема | Время | Ландшафт | Цель | Новое |\n|---|---|---|---|---|---|---|\n"
M = [l for l in LV if l['mode'] == 'mission']
out = ["# ГОПС — уровни\n",
"_Источник данных: `levels/missions.json` (66 уровней: 5 обучения, 45 миссий, 16 испытаний). Тексты и числа — черновые, правит пользователь. Темы и времена суток — из `studio/jobs/gops/make_jobs.py` (`THEMES`), оружие — `WEAPONS`, ролики — `SKETCHES`._\n",
"## 1. Сюжет глав\n",
"Серьёзной истории нет: война районов — это просто повод для 45 стычек, и все они заканчиваются тем, что проигравшие сдуваются, а победители делят семки на лавочке.\n",
"- **Глава 1 — «Расточка» (m01–m09).** Расточка заняла наш двор, гаражи и ларёк. Учимся выгонять гостей: от двух слабаков до Бугра на крыше гаража. Бугор — первый босс.",
"- **Глава 2 — «Затон» (m10–m18).** Поход на реку и завод. Затон хитрее и мокрее: острова, трансформаторы, дача с козами. Босс — Смотрящий пирса.",
"- **Глава 3 — «Первомайка» (m19–m27).** Зима, депо, кипяток. Первомайка любит холод и котлы. Здесь ломаются привычные правила: артиллерия без ходьбы, невесомость, драка без оружия. Босс — Король льда.",
"- **Глава 4 — «Чемской и Ленинский» (m28–m36).** Два района сразу, и не всегда друзья. Появляются тяжёлые игрушки: пулемёт, «Почта России», напалм. Босс — Смотрящий Чемского.",
"- **Глава 5 — «Все районы» (m37–m45).** Решающий сход на заводе: пять бригад на одном поле. Полный арсенал, самые длинные бои и финальный Авторитет.\n",
"## 2. Таблица уровней\n", "### Обучение\n",
head + "\n".join(row(l) for l in LV if l['mode'] == 'training'), ""]
for ch in range(1, 6):
    out += [f"### Миссии, глава {ch}\n", head + "\n".join(row(l, ' (босс)' if l.get('boss') else '') for l in M if l['chapter'] == ch), ""]
out += ["### Испытания на время\n", "| id | Название | Тема | Время | Ландшафт | Цель | Медали: золото / серебро / бронза, с |\n|---|---|---|---|---|---|---|"]
for l in LV:
    if l['mode'] == 'trial':
        m = l['medals_seconds']
        out.append(f"| {l['id']} | {l['title']} | {TH[l['theme']]['title']} | {TM[l['time']]} | {l['terrain']['archetype']} | {OBJ[l['objective']['type']]} | {m['gold']} / {m['silver']} / {m['bronze']} |")
out.append("")
out += ["## 3. Кривая сложности\n",
"Поле `difficulty` (0–10). Обучение — 0; миссии растут по главам, босс главы на 1–2 выше соседей; после босса следующая глава начинается на 1 ниже, чтобы игрок освоил новое.\n",
"| Глава | Сложность по миссиям | Боты противников (группы) | Бойцов у игрока | Противники |\n|---|---|---|---|---|"]
chn = {1: 'Расточка', 2: 'Затон', 3: 'Первомайка', 4: 'Чемской + Ленинский', 5: 'все пять'}
for ch in range(1, 6):
    ms = [l for l in M if l['chapter'] == ch]
    bots = Counter(e['bot'] for l in ms for e in l['enemies'])
    bs = ', '.join(f"{k} {v}" for k, v in sorted(bots.items()))
    out.append(f"| {ch} | {' '.join(str(l['difficulty']) for l in ms)} | {bs} | {min(l['player']['count'] for l in ms)}–{max(l['player']['count'] for l in ms)} | {chn[ch]} |")
out += ["",
"Новинки по главам: 1 — обрез, растяжка, рогатка, карбид, плита и отбойник, «Корсар», голубь, тротил, зонтик; 2 — огнетушитель, ракета с наводкой, дворняга, миномёт, «Калаш», козы и бабка, паяльная лампа, режим «один ход»; 3 — ледобур, заморозка, кукурузник, ванна, резинка, кеды, «Буратино», ближний бой, труба и кирпичи; 4 — пулемёт, самогон, посылка, маршрутка, невидимка, энергетик, указка, «Почта», напалм; 5 — «по понятиям», полный арсенал и сочетания.\n",
"Особые уровни: форты — m07, m27, m38; «артиллерия» (`no_walk`) — m21; низкая гравитация — m25 (0,4) и m40 (0,7); только ближний бой — m26; только верёвка — m34 (и r01); «один ход — всех» — m17, m30, m41; спасение с острова — m10; поднимающаяся вода — m16, m24, m43 (в m24 с первого хода на полную); боссы по 300 ХП — m09, m18, m27, m36, m45.\n"]

def cnt(f): return Counter(f(l) for l in M)
th = cnt(lambda l: TH[l['theme']]['title']); ob = cnt(lambda l: OBJ[l['objective']['type']])
ar = cnt(lambda l: l['terrain']['archetype']); tm = cnt(lambda l: TM[l['time']])
def line(c): return ', '.join(f"{k} — {v}" for k, v in sorted(c.items(), key=lambda x: (-x[1], x[0])))
tr = [l for l in LV if l['mode'] == 'trial']
out += ["## 4. Баланс (45 миссий)\n",
f"- **Темы** (12, каждая минимум 3 раза, подряд не повторяются): {line(th)}.",
f"- **Цели** (11 типов, максимум 10, подряд не повторяются): {line(ob)}.",
f"- **Ландшафты** (все 14 архетипов): {line(ar)}.",
f"- **Время суток:** {line(tm)}.",
f"- **Музыка:** {line(Counter(l['music'] for l in M))}.",
f"- **Бот первой группы противников:** {line(Counter(l['enemies'][0]['bot'] for l in M if l['enemies']))}.",
"- **Ролики:** после каждой третьей миссии, всего 15 из 18 (14 коротких + финал `s16-finale` после m45); `s00-intro` запускается кодом перед m01, `s11-victory` и `s12-deflate` общие.",
f"- **Испытания:** гонок {sum(1 for l in tr if l['objective']['type'] == 'race_time')}, мишеней {sum(1 for l in tr if l['objective']['type'] == 'targets')}; 12 тем, по два раза — гаражи, депо, школа и стройка.\n"]
out += ["## 5. Правила для кода (как читать missions.json)\n",
"Файл — массив из 66 объектов (`t01..t05`, `m01..m45`, `r01..r16`).\n",
"**Общие поля.** `id`, `mode` (`training`/`mission`/`trial`), `chapter` (1–5; у обучения и испытаний 0), `title`, `theme` (ключ из `THEMES`), `time` (из `times` темы), `briefing`, `tip`, `new` (текст или `null`), `difficulty` (0–10, для кривой), `music` (`menu`/`calm`/`battle`/`sudden`/`timed`), `cutscene_after` (id ролика или `null`). Победа и поражение показывают общие `s11-victory` и `s12-deflate`; перед m01 код сам запускает `s00-intro`, а после m45 идёт `s16-finale` (записан в m45).\n",
"**terrain.** `archetype` — алгоритм генерации (hills, islands, cavern, bridge, towers, pit, fortress, staircase, floating, valley, cliff, maze, arena, objects); `seed` — сид (карта одинакова у всех); `water` 0..1 — начальная доля жидкости; `props` 0..1 — плотность предметов темы.\n",
"**player.** `count` бойцов, `hp` каждого. Бригада игрока всегда `zatulinka`.\n",
"**enemies.** Массив групп: `brigade` (`rastochka`, `zaton`, `pervomayka`, `chemskoy`, `leninsky`), `count`, `hp`, `bot` (`easy`/`medium`/`hard`). Пустой массив — на мишенях и гонках. Необязательные: `boss: true` и `name` (единственный боец с большим ХП, крупная кепка), `clustered: true` (поставить кучей). Разные записи одной бригады — разные группы, один цвет кепок; враждебные бригады воюют и друг с другом.\n",
"**objective** по `type`:",
"- `eliminate` — выбить всех врагов; поражение — выбыли все свои.",
"- `survive_turns` {`turns`} — прожить N ходов своей бригады хотя бы одним бойцом.",
"- `collect_crates` {`count`} — собрать N ящиков (дотронуться своим бойцом).",
"- `rescue` {`count`, `where`} — освободить N пленных; `where` — подсказка для расстановки (остров, гараж, крыша). Пленный стоит на недоступном месте, присоединяется при касании; если он выбыл, миссия провалена.",
"- `one_turn_kill` {`turns`: 1} — выбить всех за один ход игрока; остались враги — поражение с перезапуском.",
"- `destroy_objects` {`object`, `count`} — разбить N предметов типа (barrel, transformer, boiler, fridge); расставляются на карте заранее.",
"- `reach_point` {`position` [x,y] в долях карты, `label`} или {`points`, `ordered`} — любой свой боец дошёл до точки (до всех по порядку).",
"- `protect` {`ward`, `ward_hp`, `turns`} — подопечный (`babka`, `beehive`, `locomotive`, `kiosk`) стоит на месте и не ходит; победа, если выжил N ходов; он не считается бойцом бригады.",
"- `king_of_hill` {`zone` [x,y,r], `hold_turns`} — держать круг; счётчик ходов подряд сбрасывается, если в круге есть враг.",
"- `race_time` {`checkpoints`, `time_limit`?} — пройти N контрольных точек по порядку, результат — время.",
"- `targets` {`count`, `kind`, `turns`?, `time_limit`?} — сбить N мишеней (`kind`: pop_up, moving, cans, floats, rails, baskets…), `turns`/`time_limit` — предел.\n",
"**arsenal.** `preset`: `full` — полный набор по умолчанию, `weapons` перекрывает число зарядов (0 — убрать); `limited` и `custom` — только перечисленное в `weapons`. Число: `-1` бесконечно, иначе заряды на бригаду. `delays` — через сколько ходов оружие становится доступным. Служебные «Курю», «Сдаться», «Ты иди» (`kuryu`, `pas`, `tyidi`) и «Тычок» (`tychok`) доступны всегда и в списках не перечислены, кроме `custom`-арсеналов, где он указан явно. Выпавшее из ящика оружие добавляется поверх арсенала.\n",
"**scheme.** `turn_time` (с), `round_time` (с на бой), `wind` 0..1 или `\"none\"`, `crates` 0..1 (частота), `mines` и `barrels` (мины — штук, бочки — плотность 0..1), `fall_damage` 0..1 (множитель), `sudden_death` (`water`/`one_hp`/`none`). Дополнительные необязательные: `gravity` (множитель, по умолчанию 1), `no_walk: true` (ходить нельзя), `forts: true` (форты на старте), `rising_water` 0..1 (скорость подъёма воды в ход, с первого хода), `rope_only: true` (только верёвка).\n",
"**stars.** Три независимых условия: `1` — `win`, `2` — `no_losses` (никто из своих не выбыл), `3` — одно из `turns_max` (в N ходов), `hp_percent_min` (суммарное ХП после боя не меньше N %), `shots_max` (выстрелов не более N), `time_max` (секунд не более N). У испытаний `1`, `2`, `3` — бронза, серебро, золото по времени; `medals_seconds` повторяет их.\n",
"**Что делает код при загрузке:** проверяет id оружия/темы/времени, разворачивает `arsenal.preset`, накладывает `scheme` на схему комнаты, генерирует карту по `terrain`, расставляет бригады по `enemies`, запускает `objective`.\n"]
open('G:/Claude/Shish/docs/gops/LEVELS.md', 'w', encoding='utf-8').write('\n'.join(out))
